#!/usr/bin/env python3
from pwn import *
import time

def process_byte(byte):
    # Check even parity (8-1-1)
    # Count 1s in the byte
    count = bin(byte).count('1')
    return count % 2 == 0

def try_connection(host, port):
    try:
        conn = remote(host, port)
        log.success(f"Connected to {host}:{port}")
        return conn
    except Exception as e:
        log.failure(f"Failed to connect to {host}:{port}: {e}")
        return None

def main():
    # Common CTF ports to try
    ports = [1337, 4444, 8000]
    conn = None

    # Try to connect to each port
    for port in ports:
        conn = try_connection('localhost', port)
        if conn:
            break

    if not conn:
        log.failure("Could not connect to any port")
        return

    # Buffer to store valid bytes
    buffer = []
    try:
        while True:
            # Receive one byte
            data = conn.recvn(1)
            if not data:
                break

            byte = data[0]
            log.info(f"Received byte: {hex(byte)} ({chr(byte) if 32 <= byte <= 126 else '?'})")

            # Check parity
            if process_byte(byte):
                log.success(f"Valid byte: {hex(byte)}")
                buffer.append(byte)
                conn.send(b'1')
            else:
                log.warning(f"Invalid byte: {hex(byte)}")
                conn.send(b'0')

            # Try to find flag in buffer
            buffer_data = bytes(buffer)
            if b'flag{' in buffer_data:
                start = buffer_data.find(b'flag{')
                end = buffer_data.find(b'}', start)
                if end != -1:
                    flag = buffer_data[start:end+1].decode()
                    log.success(f"Found flag: {flag}")
                    return flag

            time.sleep(0.1)  # Small delay to not overwhelm the service

    except Exception as e:
        log.failure(f"Error during communication: {e}")
    finally:
        if conn:
            conn.close()

if __name__ == '__main__':
    main()

